CREATE OR REPLACE FUNCTION public.fn_add_goal(
  p_match_id UUID,
  p_team_id UUID,
  p_player_id UUID,
  p_minute INT,
  p_goal_type VARCHAR(50)
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_home_id UUID;
  v_away_id UUID;
  v_event_id UUID := gen_random_uuid();
BEGIN
  -- 1. Verify match is live
  SELECT home_team_id, away_team_id INTO v_home_id, v_away_id FROM public.matches WHERE id = p_match_id AND status LIKE 'LIVE_%';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ERR_MATCH_NOT_LIVE: Match % is not in a live state.', p_match_id;
  END IF;

  -- 2. Insert match_event
  INSERT INTO public.match_events(id, match_id, event_type, player_id, minute, details_json)
  VALUES (v_event_id, p_match_id, 'MATCH_GOAL_ADDED', p_player_id, p_minute, jsonb_build_object('goal_type', p_goal_type, 'team_id', p_team_id));

  -- 3. Update score atomically
  IF p_team_id = v_home_id THEN
    UPDATE public.matches SET home_score = home_score + 1 WHERE id = p_match_id;
  ELSE
    UPDATE public.matches SET away_score = away_score + 1 WHERE id = p_match_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'event_id', v_event_id);
END;
$$;
